CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, name TEXT NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('customer','merchant','admin')), inviter TEXT REFERENCES users(id), created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS merchants(id TEXT PRIMARY KEY,user_id TEXT UNIQUE REFERENCES users(id),name TEXT NOT NULL,region TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected')),created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchants(id),names TEXT NOT NULL,description TEXT NOT NULL,category INTEGER NOT NULL,icon TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>0),stock INTEGER NOT NULL CHECK(stock>=0),status TEXT NOT NULL CHECK(status IN ('draft','published')),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS cart(user_id TEXT REFERENCES users(id),product_id TEXT REFERENCES products(id),sku TEXT NOT NULL,qty INTEGER NOT NULL CHECK(qty BETWEEN 1 AND 100),PRIMARY KEY(user_id,product_id,sku));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,buyer TEXT NOT NULL REFERENCES users(id),merchant_id TEXT NOT NULL REFERENCES merchants(id),group_id TEXT NOT NULL,status TEXT NOT NULL,previous_status TEXT,items TEXT NOT NULL,address TEXT NOT NULL,total INTEGER NOT NULL,cash INTEGER NOT NULL,points INTEGER NOT NULL,tracking TEXT NOT NULL DEFAULT '',reason TEXT NOT NULL DEFAULT '',refunded_cash INTEGER NOT NULL DEFAULT 0,refunded_points INTEGER NOT NULL DEFAULT 0,rule TEXT NOT NULL,created INTEGER NOT NULL,received INTEGER,settled INTEGER);
CREATE TABLE IF NOT EXISTS journal(id INTEGER PRIMARY KEY AUTOINCREMENT,asset TEXT NOT NULL CHECK(asset IN ('USDT','OPOC','ZC')),debit TEXT NOT NULL,credit TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),ref TEXT NOT NULL,kind TEXT NOT NULL,created INTEGER NOT NULL,UNIQUE(asset,ref,kind,debit,credit));
CREATE INDEX IF NOT EXISTS journal_accounts ON journal(asset,credit,debit);
CREATE TABLE IF NOT EXISTS idempotency(user_id TEXT NOT NULL,key TEXT NOT NULL,route TEXT NOT NULL,body_hash TEXT NOT NULL,result TEXT NOT NULL,PRIMARY KEY(user_id,key));
CREATE TABLE IF NOT EXISTS subscriptions(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),cash INTEGER NOT NULL,base INTEGER NOT NULL,total INTEGER NOT NULL,paid INTEGER NOT NULL DEFAULT 0,accelerated INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS exchanges(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),zc INTEGER NOT NULL,net INTEGER NOT NULL,price INTEGER NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS exchange_quotes(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),zc INTEGER NOT NULL,net INTEGER NOT NULL,price INTEGER NOT NULL,expires INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,kind TEXT NOT NULL,ref TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,UNIQUE(kind,ref));
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,body TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tickets(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),message TEXT NOT NULL,status TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS candidates(id TEXT PRIMARY KEY,names TEXT NOT NULL,cost INTEGER NOT NULL,multiplier INTEGER NOT NULL,source TEXT NOT NULL,status TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,action TEXT NOT NULL,ref TEXT NOT NULL,detail TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1),version INTEGER NOT NULL,value TEXT NOT NULL);
INSERT OR IGNORE INTO migrations VALUES(1,unixepoch()*1000);

